.certificate-title {
    margin-top: -1in;
    position: relative;
    top: -50px;
}

.certificate-text {
    font-family: 'Cairo', sans-serif;
    font-weight: bold;
    color: black;
}



.certified-text {
    font-family: 'Readex Pro', sans-serif;
    font-size: 1.2rem;
    color: black;
}

.inner-border {
    background: url(https://lms.one-fm.com/assets/one_lms/images/Certifactes1fm-bg.png);
    background-repeat: round;
    background-size: cover;
    max-width: 11in;
    border-radius: 8px;
    text-align: center;
    padding: 5.5rem;
    width: 9in;

}

.certificate-name {
    font-family: 'Readex Pro', sans-serif;
    font-size: 2.5rem;
    font-style: italic;
    color: black;
}

.certificate-right-align{
    right: -36px;
    justify-content: end;
}

.onefm-font{
    font-family: 'Readex Pro', sans-serif;
    font-size: 16px;
}

.certificate-footer {
    margin: 2rem auto 7px;
    width: 100%;
    padding: 0;
    position: relative;
    top: 49px;
}

.certificate-footer-item {
    color: #192734;
}

.cursive-font {
    font-family: cursive;
    font-weight: 600;
}

.certificate-divider {
    margin: 0.5rem 0px;
    border-top: 1px solid;
}


.training-details {
     font-family: 'Readex Pro', sans-serif;
    font-size: 1.2rem;
}

.certificate-no {
    font-family: Arial, sans-serif;
}
